    private static final String FIND_ENTRIES =
            "SELECT {r:" + ItemModel.PK + "} FROM {" + CCConfigEntryModel._TYPECODE + " AS r}"
            + " WHERE {r:" + CCConfigEntryModel.CONFIGURATION + "}=?configuration"
            + " AND {r:" + CCConfigEntryModel.ENABLED + "}=?enabled"
