import com.conversational.commerce.core.engine.model.Domain.Order;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.ToolRegistry.Call;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import com.conversational.commerce.core.engine.rules.ReplenishmentRule;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** NEXT_ORDER (SC-01, SC-09): [history, replenishment net of pending, pending] then complements, rank, hydrate. */
public class NextOrderWorkflow extends AbstractWorkflow
{
    @Override
    public Intent intent()
    {
        return Intent.NEXT_ORDER;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        final List<ToolResult> group = state.step("step.checkingHistory", () -> toolRegistry.executeParallel(state,
                List.of(new Call("getCustomerPurchaseHistory", Map.of("windowDays", 180)),
                        new Call("getReplenishmentRecommendations", Map.of("netPending", true)),
                        new Call("getPendingOrders", Map.of())),
                parallelTimeoutSeconds()));
        final List<ReplenishmentRule.Item> due = group.get(1).as();
        final List<Order> pending = group.get(2).as();
        if (due.isEmpty())
        {
            return Output.of(List.of(), "next_order_none", Map.of(), Map.of());
        }
        final List<Recommendation> recommendations = new ArrayList<>();
        for (final ReplenishmentRule.Item item : due)
        {
            recommendations.add(hydrator.recommendation(state, item.code(), item.suggestedQuantity(),
                    item.overdue() ? "OVERDUE" : "DUE", true));
        }
        final List<Block> blocks = new ArrayList<>();
        blocks.add(Block.recommendations("b-due", recommendations, true));
        final ToolResult complements = tool(state, "step.lookingForComplements", "getComplementaryProducts",
                Map.of("codes", due.stream().map(ReplenishmentRule.Item::code).toList()));
        final List<com.conversational.commerce.core.engine.rules.CoPurchaseRule.Suggestion> suggestions = complements.as();
        if (!suggestions.isEmpty())
        {
            final List<ProductCard> cards = suggestions.stream()
                    .map(s -> hydrator.card(state, s.code(), Map.of("reason", "COMPLEMENT"))).toList();
            blocks.add(Block.productCards("b-complements", cards));
        }
        final Map<String, String> slots = new LinkedHashMap<>();
        slots.put("dueCount", String.valueOf(due.size()));
        slots.put("overdueCount", String.valueOf(due.stream().filter(ReplenishmentRule.Item::overdue).count()));
        slots.put("pendingCount", String.valueOf(pending.size()));
        final Map<String, Object> facts = new LinkedHashMap<>();
        facts.put("dueCount", due.size());
        facts.put("pendingOrders", pending.size());
        facts.put("estimate", true);
        return new Output(blocks, "next_order", facts, slots, null, List.of("ADD_ALL_TO_LIST"), null);
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Domain.Order;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.MoneyFormat;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** ORDER_LOOKUP (SC-06): filters extracted by the model are range-checked, resolved to dates in Java, scoped to the customer. */
public class OrderLookupWorkflow extends AbstractWorkflow
{
    @Override
    public Intent intent()
    {
        return Intent.ORDER_LOOKUP;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        final Map<String, Object> args = new LinkedHashMap<>();
        args.put("status", decision.orderStatus());
        if (decision.orderMinAmount() != null)
        {
            args.put("minTotalMinor", MoneyFormat.toMinor(decision.orderMinAmount()));
        }
        final LocalDate today = state.today;
        switch (decision.orderPeriod())
        {
            case "LAST_MONTH" ->
            {
                final LocalDate first = today.withDayOfMonth(1).minusMonths(1);
                args.put("fromDate", first.toString());
                args.put("toDate", first.withDayOfMonth(first.lengthOfMonth()).toString());
            }
            case "LAST_30_DAYS" ->
            {
                args.put("fromDate", today.minusDays(30).toString());
                args.put("toDate", today.toString());
            }
            case "THIS_MONTH" ->
            {
                args.put("fromDate", today.withDayOfMonth(1).toString());
                args.put("toDate", today.toString());
            }
            default ->
            {
            }
        }
        final ToolResult found = tool(state, "step.searchingOrders", "searchOrders", args);
        final List<Order> orders = found.as();
        if (orders.isEmpty())
        {
            return Output.of(List.of(), "order_none", Map.of(), Map.of());
        }
        // Tracking for the latest match: read from the same customer-scoped data (FUTURE SCOPE: carrier tracking).
        final Order latest = orders.get(0);
        if (decision.wantsLatestTracking())
        {
            tool(state, "step.checkingDelivery", "getOrderTracking", Map.of("orderCode", latest.code()));
        }
        final Block block = Block.orders("b-orders", orders.stream().map(hydrator::order).toList());
        return Output.of(List.of(block), "order_lookup", Map.of("count", orders.size()), Map.of("count", String.valueOf(orders.size())));
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.Comparison;
import com.conversational.commerce.core.engine.model.Blocks.ComparisonRow;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Domain.Product;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/** PRODUCT_QA (PD-03, PD-05): grounded in approved catalogue fields only. */
public class ProductQaWorkflow extends AbstractWorkflow
{
    @Override
    public Intent intent()
    {
        return Intent.PRODUCT_QA;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        List<String> codes = decision.codes();
        if (codes.isEmpty() && !decision.keywords().isEmpty())
        {
            final ToolResult search = tool(state, "step.searchingCatalogue", "searchProducts",
                    Map.of("keywords", decision.keywords(), "limit", 1));
            final List<Product> found = search.as();
            codes = found.stream().map(Product::code).toList();
        }
        final ToolResult details = tool(state, "step.readingProductData", "getProductDetails", Map.of("codes", codes));
        final List<Product> products = details.as();
        if (products.isEmpty())
        {
            return Output.of(List.of(), "qa_none", Map.of(), Map.of());
        }
        final Product product = products.get(0);
        final List<ComparisonRow> rows = new ArrayList<>();
        product.attributes().forEach((k, v) -> rows.add(new ComparisonRow(k, List.of(v))));
        final Comparison table = new Comparison(List.of(product.name()), rows, List.of());
        return new Output(List.of(Block.comparison("b-details", table)), "product_qa", Map.of("product", product.code()), Map.of(),
                table, List.of(), product.code());
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.ListLine;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import com.conversational.commerce.core.engine.tools.QuickOrderValidateTool.Line;
import com.conversational.commerce.core.engine.tools.QuickOrderValidateTool.Status;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * QUICK_ORDER (SC-03): deterministic grammar parse of the dealer's own (translated) text, then catalogue validation.
 * ASSUMPTION: the design's "model parse of residual lines" is not used; unresolved lines are returned to the dealer instead.
 */
public class QuickOrderWorkflow extends AbstractWorkflow
{
    @Override
    public Intent intent()
    {
        return Intent.QUICK_ORDER;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        final ToolResult result = tool(state, "step.readingYourList", "validateQuickOrderLines",
                Map.of("rawText", state.workingMessage));
        final List<Line> lines = result.as();
        final List<ListLine> listLines = new ArrayList<>();
        final List<String> issues = new ArrayList<>();
        int ok = 0;
        for (final Line line : lines)
        {
            if (line.resolvedCode() != null && line.quantity() != null && line.status() != Status.QUANTITY_NEEDED)
            {
                listLines.add(hydrator.line(state, line.resolvedCode(), line.quantity(), "quick order", line.issue()));
                ok++;
            }
            else
            {
                issues.add(line.rawText() + ": " + (line.issue() == null ? line.status().name() : line.issue()));
            }
        }
        final List<Block> blocks = new ArrayList<>();
        blocks.add(Block.purchaseList("b-list", listLines));
        for (final String issue : issues)
        {
            blocks.add(Block.notice("b-issue-" + blocks.size(), "quickOrderIssue", issue));
        }
        final Map<String, String> slots = new LinkedHashMap<>();
        slots.put("lineCount", String.valueOf(lines.size()));
        slots.put("okCount", String.valueOf(ok));
        slots.put("issueCount", String.valueOf(lines.size() - ok));
        return new Output(blocks, "quick_order", Map.of("lines", lines.size()), slots, null, List.of(), null);
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Blocks.Block;
import com.conversational.commerce.core.engine.model.Blocks.ListLine;
import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Domain.Order;
import com.conversational.commerce.core.engine.model.Domain.OrderLine;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.ToolResult;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import com.conversational.commerce.core.engine.model.Domain.Product;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** REORDER (PA-07): lines of one of the customer's own orders become a labelled demo list; discontinued lines use replacements. */
public class ReorderWorkflow extends AbstractWorkflow
{
    private static final Pattern ORDER_CODE = Pattern.compile("\\b(?:ORD|PO)[-#]?\\d{4,}\\b|\\b\\d{8}\\b");

    @Override
    public Intent intent()
    {
        return Intent.REORDER;
    }

    @Override
    public Output run(final TurnState state, final Decision decision)
    {
        final Matcher m = ORDER_CODE.matcher(state.workingMessage);
        final ToolResult orderResult = m.find()
                ? tool(state, "step.findingOrder", "getOrderById", Map.of("orderCode", m.group()))
                : tool(state, "step.findingOrder", "getLatestOrder", Map.of());
        final List<Order> found = orderResult.as();
        if (found.isEmpty())
        {
            return Output.of(List.of(), "reorder_none", Map.of(), Map.of());
        }
        final List<ListLine> lines = new ArrayList<>();
        for (final OrderLine line : found.get(0).lines())
        {
            final ToolResult details = toolRegistry.execute(state, "getProductDetails", Map.of("codes", List.of(line.productCode())));
            final List<Product> products = details.as();
            String code = line.productCode();
            String issue = null;
            if (!products.isEmpty() && products.get(0).discontinued())
            {
                final ToolResult alt = toolRegistry.execute(state, "getAlternatives", Map.of("code", code));
                final List<Product> alternatives = alt.as();
                if (alternatives.isEmpty())
                {
                    lines.add(hydrator.line(state, code, 0, "reorder", "Discontinued, no replacement"));
                    continue;
                }
                issue = code + " replaced by " + alternatives.get(0).code();
                code = alternatives.get(0).code();
            }
            lines.add(hydrator.line(state, code, line.quantity(), "reorder", issue));
        }
        return Output.of(List.of(Block.purchaseList("b-reorder", lines)), "reorder", Map.of("lines", lines.size()),
                Map.of("lineCount", String.valueOf(lines.size())));
    }
}

package com.conversational.commerce.core.engine.orchestrator.workflow;

import com.conversational.commerce.core.engine.model.Decision;
import com.conversational.commerce.core.engine.model.Intent;
import com.conversational.commerce.core.engine.orchestrator.TurnState;
import com.conversational.commerce.core.engine.orchestrator.WorkflowTemplate;
import java.util.List;
import java.util.Map;

/** OFF_TOPIC, UNSUPPORTED, CLARIFY and SWITCH_PACK: no tools, fixed text (CF-06, D28). SC-10 is configuration only. */
public final class StaticWorkflows
{
    private StaticWorkflows()
    {
    }

    public abstract static class Fixed implements WorkflowTemplate
    {
        private final Intent intent;
        private final String templateKey;

        Fixed(final Intent intent, final String templateKey)
        {
            this.intent = intent;
            this.templateKey = templateKey;
        }

        @Override
        public Intent intent()
        {
            return intent;
        }

        @Override
        public Output run(final TurnState state, final Decision decision)
        {
            return new Output(List.of(), templateKey, Map.of(), Map.of(), null, List.of(), null);
        }
    }

    public static class OffTopicWorkflow extends Fixed
    {
        public OffTopicWorkflow()
        {
            super(Intent.OFF_TOPIC, "off_topic");
        }
    }

    public static class UnsupportedWorkflow extends Fixed
    {
        public UnsupportedWorkflow()
        {
            super(Intent.UNSUPPORTED, "unsupported");
        }
    }

    public static class ClarifyWorkflow extends Fixed
    {
        public ClarifyWorkflow()
        {
            super(Intent.CLARIFY, "clarify");
        }
    }

    public static class SwitchPackWorkflow extends Fixed
    {
        public SwitchPackWorkflow()
        {
            super(Intent.SWITCH_PACK, "unsupported");
        }
    }
}

package com.conversational.commerce.core.engine.provider;

import com.conversational.commerce.core.engine.config.CcConfigurationService;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import de.hybris.platform.servicelayer.exceptions.SystemException;
import jakarta.annotation.Resource;
import java.io.IOException;
import java.util.Map;
import org.apache.commons.lang3.StringUtils;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

/**
 * Shared HTTP handling. Errors follow the owner's convention: non-200 logs the status only (the body may echo user
 * content) and throws SystemException; null content throws SystemException; InterruptedException restores the flag.
 */
public abstract class AbstractHttpAdapter implements ModelProviderAdapter
{
    private static final Logger LOG = LogManager.getLogger(AbstractHttpAdapter.class);
    protected static final ObjectMapper MAPPER = new ObjectMapper();
    private static final String TIMEOUT_KEY = "cc.http.requestTimeoutMs";
    private static final String CONNECT_TIMEOUT_KEY = "cc.http.connectTimeoutMs";

    @Resource(name = "ccConfigurationService")
    protected CcConfigurationService configurationService;

    private HttpTransport transport;

    public void setConfigurationService(final CcConfigurationService configurationService)
    {
        this.configurationService = configurationService;
    }

    public void setTransport(final HttpTransport transport)
    {
        this.transport = transport;
    }

    @Override
    public String tier()
    {
        return configurationService.getString("cc.provider." + providerCode() + ".tier", "paid");
    }

    @Override
    public boolean isAvailable()
    {
        return StringUtils.isNotBlank(baseUrl()) && StringUtils.isNotBlank(apiKey())
                && configurationService.getBoolean("cc.provider." + providerCode() + ".enabled", true);
    }

    protected String baseUrl()
    {
        return configurationService.getString("cc.provider." + providerCode() + ".baseUrl", "");
    }

    /** Keys are read by alias and never logged. ASSUMPTION: alias defaults to the provider code. */
    protected String apiKey()
    {
        final String alias = configurationService.getString("cc.provider." + providerCode() + ".keyAlias", providerCode());
        return configurationService.getString("cc.provider.key." + alias, "");
    }

    protected abstract String endpoint(String model);

    protected abstract Map<String, String> headers();

    protected abstract String buildBody(String model, ModelRequest request) throws JsonProcessingException;

    protected abstract JsonNode extractContent(JsonNode response);

    protected abstract int[] extractUsage(JsonNode response);

    @Override
    public ModelResult call(final String model, final ModelRequest request)
    {
        final long start = System.currentTimeMillis();
        try
        {
            final String body = buildBody(model, request);
            final HttpTransport.Response response = getTransport().post(baseUrl() + endpoint(model), headers(), body,
                    configurationService.getInt(TIMEOUT_KEY, 8000));
            if (response.status() != 200)
            {
                LOG.warn("Model provider {} returned status {}", providerCode(), response.status()); // status only
                throw new SystemException("Model provider returned status " + response.status());
            }
            final JsonNode root = MAPPER.readTree(response.body());
            final JsonNode content = root == null ? null : extractContent(root);
            if (content == null || content.isNull() || content.isMissingNode())
            {
                throw new SystemException("Model provider returned no content");
            }
            final int[] usage = extractUsage(root);
            return new ModelResult(content, usage[0], usage[1], providerCode(), model, System.currentTimeMillis() - start);
        }
        catch (final InterruptedException e)
        {
            Thread.currentThread().interrupt();
            throw new SystemException("Model call interrupted", e);
        }
        catch (final IOException e)
        {
            // ASSUMPTION: remaining catch blocks were truncated in the owner's screenshot (docs/assumptions.md AS-06).
            LOG.warn("Model provider {} call failed: {}", providerCode(), e.getClass().getSimpleName());
            throw new SystemException("Model provider call failed", e);
        }
    }

    private HttpTransport getTransport()
    {
        if (transport == null)
        {
            transport = new JdkHttpTransport(configurationService.getInt(CONNECT_TIMEOUT_KEY, 3000));
        }
        return transport;
    }

    /** Parses model text as JSON; a non-JSON answer is a schema failure the router may retry. */
    protected JsonNode parseJsonText(final String text)
    {
        try
        {
            return MAPPER.readTree(text);
        }
        catch (final JsonProcessingException e)
        {
            return null;
        }
    }

    protected static ObjectNode object()
    {
        return MAPPER.createObjectNode();
    }
}

package com.conversational.commerce.core.engine.provider;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
