import com.conversational.commerce.core.dao.CcOrderDao;
import com.conversational.commerce.core.engine.gateway.OrderGateway;
import com.conversational.commerce.core.engine.model.Domain.Order;
import com.conversational.commerce.core.engine.model.Domain.OrderLine;
import com.conversational.commerce.core.engine.model.Domain.OrderStatus;
import de.hybris.platform.core.model.order.AbstractOrderEntryModel;
import de.hybris.platform.core.model.order.OrderModel;
import de.hybris.platform.core.model.user.CustomerModel;
import de.hybris.platform.ordersplitting.model.ConsignmentModel;
import de.hybris.platform.servicelayer.user.UserService;
import jakarta.annotation.Resource;
import java.math.BigDecimal;
import java.time.ZoneId;
import java.util.Date;
import java.util.List;
import java.util.Optional;
import org.apache.commons.lang3.StringUtils;

/** Customer-scoped order access. The customer id is the uid from the Spring Security context (via the facade). */
public class PlatformOrderGateway implements OrderGateway
{
    // FUTURE SCOPE: unit-level order access (D33).

    @Resource(name = "ccOrderDao")
    private CcOrderDao ccOrderDao;

    @Resource
    private UserService userService;

    @Override
    public List<Order> ordersOf(final String customerId)
    {
        final CustomerModel customer = customer(customerId);
        final Date since = Date.from(java.time.LocalDate.now().minusDays(730).atStartOfDay(ZoneId.systemDefault()).toInstant());
        return ccOrderDao.findSince(customer, since).stream().map(this::convert).toList();
    }

    @Override
    public Optional<Order> orderByCode(final String customerId, final String code)
    {
        return Optional.ofNullable(ccOrderDao.findByCode(code, customer(customerId))).map(this::convert);
    }

    private CustomerModel customer(final String customerId)
    {
        return (CustomerModel) userService.getUserForUID(customerId);
    }

    private Order convert(final OrderModel model)
    {
        final List<OrderLine> lines = model.getEntries().stream()
                .map((AbstractOrderEntryModel e) -> new OrderLine(e.getProduct().getCode(), e.getQuantity().intValue())).toList();
        final BigDecimal total = BigDecimal.valueOf(model.getTotalPrice() == null ? 0 : model.getTotalPrice());
        String tracking = null;
        if (model.getConsignments() != null)
        {
            for (final ConsignmentModel c : model.getConsignments())
            {
                if (StringUtils.isNotBlank(c.getTrackingID()))
                {
                    tracking = c.getTrackingID();
                    break;
                }
            }
        }
        // FUTURE SCOPE: carrier tracking (D10): only the Commerce-held reference is returned here.
        return new Order(model.getCode(), model.getUser().getUid(), model.getDate().toInstant().atZone(ZoneId.systemDefault()).toLocalDate(),
                map(model.getStatus() == null ? null : model.getStatus().getCode()), total.movePointRight(2).longValue(),
                model.getCurrency() == null ? "" : model.getCurrency().getIsocode(), lines, tracking);
    }

    private OrderStatus map(final String code)
    {
        if (code == null)
        {
            return OrderStatus.PENDING;
        }
        return switch (code)
        {
            case "COMPLETED", "DELIVERED" -> OrderStatus.DELIVERED;
            case "CANCELLED", "CANCELLING" -> OrderStatus.CANCELLED;
            case "SHIPPED", "DISPATCHED" -> OrderStatus.SHIPPED;
            case "CREATED", "PENDING_APPROVAL", "PENDING_APPROVAL_FROM_MERCHANT" -> OrderStatus.PENDING;
            default -> OrderStatus.PROCESSING; // ASSUMPTION: unknown platform statuses are treated as in progress
        };
    }
}

package com.conversational.commerce.core.platform;

import com.conversational.commerce.core.dao.CcProductSearchDao;
import com.conversational.commerce.core.engine.gateway.PriceGateway;
import de.hybris.platform.jalo.order.price.PriceInformation;
import de.hybris.platform.core.model.product.ProductModel;
import de.hybris.platform.commerceservices.price.CommercePriceService;
import de.hybris.platform.store.services.BaseStoreService;
import jakarta.annotation.Resource;
import java.math.BigDecimal;
import java.util.OptionalLong;

/**
 * Customer-specific price through the platform price service, evaluated in the session of the authenticated customer.
 * ASSUMPTION (AS-04): the chat request runs in the customer's session, so contract prices apply. Never sent to a model.
 */
public class PlatformPriceGateway implements PriceGateway
{
    @Resource(name = "ccProductSearchDao")
    private CcProductSearchDao ccProductSearchDao;

    @Resource
    private CommercePriceService commercePriceService;

    @Resource
    private BaseStoreService baseStoreService;

    @Override
    public OptionalLong unitPriceMinor(final String customerId, final String productCode)
    {
        final ProductModel product = ccProductSearchDao.findByCode(productCode);
        if (product == null)
        {
            return OptionalLong.empty();
        }
        final PriceInformation info = commercePriceService.getWebPriceForProduct(product);
        if (info == null || info.getPriceValue() == null)
        {
            return OptionalLong.empty();
        }
        return OptionalLong.of(BigDecimal.valueOf(info.getPriceValue().getValue()).movePointRight(2).longValue());
    }

    @Override
    public String currency()
    {
        return baseStoreService.getCurrentBaseStore() == null ? "INR"
                : baseStoreService.getCurrentBaseStore().getDefaultCurrency().getIsocode();
    }
}

package com.conversational.commerce.core.platform;

import com.conversational.commerce.core.dao.CcFeedbackDao;
import com.conversational.commerce.core.dao.CcInterestEventDao;
import com.conversational.commerce.core.dao.CcUsageCounterDao;
import com.conversational.commerce.core.engine.orchestrator.RetentionService.RetentionStore;
import jakarta.annotation.Resource;
import java.time.Instant;
import java.time.ZoneId;
import java.util.Date;

public class PlatformRetentionStore implements RetentionStore
{
    private static final int BATCH = 500;

    @Resource(name = "ccInterestEventDao")
    private CcInterestEventDao ccInterestEventDao;

    @Resource(name = "ccFeedbackDao")
    private CcFeedbackDao ccFeedbackDao;

    @Resource(name = "ccUsageCounterDao")
    private CcUsageCounterDao ccUsageCounterDao;

    @Override
    public int purgeInterestEventsBefore(final Instant cutoff)
    {
        return loop(() -> ccInterestEventDao.purgeBefore(Date.from(cutoff), BATCH));
    }

    @Override
    public int purgeFeedbackBefore(final Instant cutoff)
    {
        return loop(() -> ccFeedbackDao.purgeBefore(Date.from(cutoff), BATCH));
    }

    @Override
    public int purgeUsageCountersBefore(final Instant cutoff)
    {
        final String key = cutoff.atZone(ZoneId.systemDefault()).toLocalDate().toString();
        return loop(() -> ccUsageCounterDao.purgePeriodsBefore(key, BATCH));
    }

    private int loop(final java.util.function.IntSupplier batch)
    {
        int total = 0;
        int n;
        do
        {
            n = batch.getAsInt();
            total += n;
        }
        while (n >= BATCH);
        return total;
    }
}

package com.conversational.commerce.core.platform;

import com.conversational.commerce.core.dao.CcUsageCounterDao;
import com.conversational.commerce.core.engine.gateway.UsageCounterStore;
import com.conversational.commerce.core.model.CCUsageCounterModel;
import de.hybris.platform.core.model.user.CustomerModel;
import de.hybris.platform.servicelayer.model.ModelService;
import de.hybris.platform.servicelayer.user.UserService;
import jakarta.annotation.Resource;

/**
 * Usage counters (PL-06). ASSUMPTION (AS-04): the read-modify-write below is not atomic across nodes; the unique index on
 * (customer, periodKey) prevents duplicate rows and a lost update only under-counts by one message. Batch or use an
 * SQL increment if the client needs strict caps.
 */
public class PlatformUsageCounterStore implements UsageCounterStore
{
    @Resource(name = "ccUsageCounterDao")
    private CcUsageCounterDao ccUsageCounterDao;

    @Resource
    private ModelService modelService;

    @Resource
    private UserService userService;

    @Override
    public synchronized long[] add(final String customerId, final String periodKey, final int messages, final int tokens)
    {
        final CustomerModel customer = (CustomerModel) userService.getUserForUID(customerId);
        CCUsageCounterModel counter = ccUsageCounterDao.find(customer, periodKey);
        if (counter == null)
        {
            counter = modelService.create(CCUsageCounterModel.class);
            counter.setCustomer(customer);
            counter.setPeriodKey(periodKey);
            counter.setMessageCount(0);
            counter.setTokenCount(0L);
        }
        counter.setMessageCount(counter.getMessageCount() + messages);
        counter.setTokenCount(counter.getTokenCount() + tokens);
        modelService.save(counter);
        return new long[] { counter.getMessageCount(), counter.getTokenCount() };
    }

    @Override
    public long[] get(final String customerId, final String periodKey)
    {
        final CCUsageCounterModel counter = ccUsageCounterDao.find((CustomerModel) userService.getUserForUID(customerId), periodKey);
        return counter == null ? new long[2] : new long[] { counter.getMessageCount(), counter.getTokenCount() };
    }
}

package com.conversational.commerce.core.platform;

import com.conversational.commerce.core.engine.config.ConfigSource;
import de.hybris.platform.servicelayer.config.ConfigurationService;
import jakarta.annotation.Resource;
import java.util.Optional;

/** Layer 1/2: project.properties, local.properties, environment, Cloud secret (the platform merges them). */
public class PropertiesConfigSource implements ConfigSource
{
    @Resource
    private ConfigurationService configurationService;

    @Override
    public Optional<String> get(final String key)
    {
        if (!configurationService.getConfiguration().containsKey(key))
        {
            return Optional.empty();
        }
        return Optional.ofNullable(configurationService.getConfiguration().getString(key));
    }
}

